          "id": "karacaoglan",
          "ad": "Karacaoğlan Aşk Şiirleri",
          "tema": "Sosyal Aşkın Tabakası: Emek, Halk, Yaşam",
          "karakterler": {
            "kahraman_1": {
              "arketipi": "İşçi, destancı, aşık",
