        "id": "r_vulnerability_soften",
        "priority": 90,
        "if": { "signal": "vulnerability", "op": ">", "value": 0.7 },
        "then": {
          "force_modules": ["gentle_empathy", "clarify_frame"],
          "block_modules": ["soft_paradox"],
